// WF-01 Node 2: Trích xuất, làm sạch IP và thông tin mạng
try {
  const input = $input.first().json;
  const raw = input.body?.data || input.body || input.data || input;

  let ip = String(raw.ip || raw.clientIp || raw.remoteAddress || '127.0.0.1').trim();
  if (ip.startsWith('::ffff:')) {
    ip = ip.replace('::ffff:', '');
  }

  const email = String(raw.email || raw.targetEmail || 'unknown@company.com').toLowerCase().trim();
  const userAgent = String(raw.userAgent || raw.headers?.['user-agent'] || 'Unknown-Device').substring(0, 150);
  const reason = String(raw.reason || 'LOGIN_FAILED').trim();
  const targetRole = String(raw.targetRole || raw.role || 'USER').toUpperCase();
  const timestamp = raw.timestamp || new Date().toISOString();

  return [{
    json: {
      ip,
      email,
      userAgent,
      reason,
      targetRole,
      timestamp,
      isPrivilegedTarget: ['SUPERADMIN', 'HR', 'ADMIN'].includes(targetRole)
    }
  }];
} catch (err) {
  throw new Error('[WF-01 Sanitize] Error: ' + err.message);
}

// WF-01 Node 3: Bộ đếm tần suất thất bại
const item = $input.first().json;
const baseAttempts = Number(item.attempts || 5);
const totalFailedAttempts = item.isPrivilegedTarget ? baseAttempts + 1 : baseAttempts;
const isThresholdReached = totalFailedAttempts >= 5;

return [{
  json: {
    ...item,
    failedAttempts: totalFailedAttempts,
    isThresholdReached,
    detectionWindowMinutes: 15
  }
}];

// WF-01 Node 5: Tính thời gian khóa IP
const item = $input.first().json;
const banMinutes = item.isPrivilegedTarget ? 1440 : 60;
const banUntil = new Date(Date.now() + banMinutes * 60 * 1000).toISOString();
const incidentId = 'INC-BRUTE-' + Date.now().toString(36).toUpperCase();

return [{
  json: {
    ...item,
    incidentId,
    banMinutes,
    banUntil,
    banAction: 'TEMPORARY_IP_BLOCK'
  }
}];

// WF-01 Node 7: Gemini AI Threat Classifier
let node5 = {};
try {
  node5 = $('5. Calc Ban Window & Incident ID').first()?.json || $('5. Calc Ban Window & Incident ID1').first()?.json || {};
} catch (e) {
  node5 = {};
}
let node2 = {};
try {
  node2 = $('2. Sanitize & Parse Network Info').first()?.json || $('2. Sanitize & Parse Network Info1').first()?.json || {};
} catch (e) {
  node2 = {};
}
const input = $input.first()?.json || {};
const item = { ...node2, ...node5, ...(input.data || input) };

const ip = item.ip || '192.168.1.188';
const email = item.email || 'superadmin@company.com';
const failedAttempts = Number(item.failedAttempts || 5);
const incidentId = item.incidentId || ('INC-BRUTE-' + Date.now().toString(36).toUpperCase());
const isPrivilegedTarget = Boolean(item.isPrivilegedTarget || ['SUPERADMIN', 'HR', 'ADMIN'].includes(String(item.targetRole || '').toUpperCase()) || email.includes('admin') || email.includes('hr'));
const isCritical = isPrivilegedTarget || failedAttempts >= 5;
const riskTier = isCritical ? 'CRITICAL_ATTACK' : 'HIGH_SUSPICIOUS';
const banMinutes = Number(item.banMinutes || (isPrivilegedTarget ? 1440 : 60));
const banUntil = item.banUntil || new Date(Date.now() + banMinutes * 60 * 1000).toLocaleTimeString('vi-VN');
const targetRole = item.targetRole || (isPrivilegedTarget ? 'SUPERADMIN' : 'USER');
const aiAssessment = isCritical
  ? 'CẢNH BÁO ĐỎ: Phát hiện dấu hiệu Credential Stuffing tấn công trực diện vào tài khoản Quản trị cấp cao. Khuyến nghị duy trì phong tỏa IP và bắt buộc bật 2FA.'
  : 'CẢNH BÁO VÀNG: Tần suất gõ sai mật khẩu vượt ngưỡng thông thường. Đã thực hiện khóa tạm thời 60 phút để ngăn chặn rủi ro.';

return [{
  json: {
    ...item,
    ip,
    email,
    targetRole,
    incidentId,
    failedAttempts,
    banMinutes,
    banUntil,
    isPrivilegedTarget,
    riskTier,
    aiAssessment
  }
}];
